    {
      "box_2d": [36, 148, 48, 171],
      "text_content": "(14)"
    },
    {
      "box_2d": [77, 148, 187, 203],
      "text_content": "“Production machinery”"
    },
    {
      "box_2d": [189, 176, 474, 454],
      "text_content": "means any machine or apparatus that processes or produces a product intended for eventual sale. This includes all component parts of such machine or apparatus and any other equipment used exclusively with such machine or apparatus. However, “production machinery” does not mean any boiler, or fired or unfired pressure vessel."
    },
    {
      "box_2d": [225, 143, 238, 173],
      "text_content": "(15)"
    },
    {
      "box_2d": [226, 176, 486, 454],
      "text_content": "“Schedule” means the Equipment Breakdown Endorsement section shown in the Miscellaneous Policy Level Coverages section of the Commercial Property Schedule."
    },
    {
      "box_2d": [299, 148, 314, 171],
      "text_content": "(16)"
    },
    {
      "box_2d": [300, 176, 353, 237],
      "text_content": "“Vehicle” means,"
    },
    {
      "box_2d": [300, 237, 468, 454],
      "text_content": "as respects this endorsement only, any machine or apparatus that is used for transportation or moves under its own power. “Vehicle” includes, but is not limited to, car, truck, bus, trailer, train, aircraft, watercraft, forklift, bulldozer, tractor or harvester. However, any property that is stationary, permanently installed at a covered location and that receives electrical power from an external power source, will not be considered a “vehicle”."
    },
    {
      "box_2d": [36, 518, 48, 533],
      "text_content": "(5)"
    },
    {
      "box_2d": [36, 597, 48, 611],
      "text_content": "(6)"
    },
    {
      "box_2d": [36, 628, 48, 642],
      "text_content": "(7)"
    },
    {
      "box_2d": [54, 628, 216, 906],
      "text_content": "Flood, surface water, waves, tides, tidal waves, overflow of any body of water, or their spray, all whether driven by wind or not; mudslide or mudflow; or water that backs up or overflows from a sewer, drain or sump. However, if electrical “covered equipment” requires drying out because of the above, we will pay for the direct expenses of such drying out subject to the applicable Limit of Insurance and deductible for Building or Business Personal Property, whichever applies;"
    },
    {
      "box_2d": [222, 597, 234, 619],
      "text_content": "Vandalism;"
    },
    {
      "box_2d": [240, 628, 296, 906],
      "text_content": "Your failure to use all reasonable means to protect Covered Property from damage following an “accident” or “electronic circuitry impairment”."
    },
    {
      "box_2d": [472, 88, 484, 223],
      "text_content": "2. EXCLUSIONS"
    },
    {
      "box_2d": [302, 570, 315, 583],
      "text_content": "b."
    },
    {
      "box_2d": [303, 598, 377, 906],
      "text_content": "Coverage under this endorsement does not apply to an “accident” or “electronic circuitry impairment” caused by or resulting from:"
    },
    {
      "box_2d": [379, 598, 391, 620],
      "text_content": "(1)"
    },
    {
      "box_2d": [379, 628, 409, 906],
      "text_content": "Lightning;"
    },
    {
      "box_2d": [393, 597, 405, 621],
      "text_content": "(2)"
    },
    {
      "box_2d": [393, 628, 409, 906],
      "text_content": "Windstorm or hail. However this"
    },
    {
      "box_2d": [411, 628, 423, 825],
      "text_content": "exclusion does not apply when:"
    },
    {
      "box_2d": [413, 629, 427, 651],
      "text_content": "(a)"
    },
    {
      "box_2d": [413, 659, 497, 906],
      "text_content": "“Covered equipment” located within a building or structure suffers an “accident” or “electronic circuitry impairment” that results from wind-blown rain, snow, sand or dust; and"
    },
    {
      "box_2d": [500, 629, 514, 650],
      "text_content": "(b)"
    },
    {
      "box_2d": [500, 659, 557, 906],
      "text_content": "The building or structure did not first sustain wind or hail damage to its roof or walls through which the rain, snow, sand or dust entered."
    },
    {
      "box_2d": [492, 117, 574, 454],
      "text_content": "As respects this endorsement only, with the exception of “power outage”; all exclusions within the Exclusions section of the Property Coverage Form or Causes of Loss form apply, except as modified below and to the extent that coverage is specifically provided by this endorsement."
    },
    {
      "box_2d": [561, 600, 575, 621],
      "text_content": "(3)"
    },
    {
      "box_2d": [561, 628, 602, 906],
      "text_content": "Smoke; aircraft or vehicles; riot or civil commotion; sprinkler leakage; elevator collision;"
    },
    {
      "box_2d": [577, 117, 587, 345],
      "text_content": "The following exclusions are added:"
    },
    {
      "box_2d": [610, 599, 623, 622],
      "text_content": "(4)"
    },
    {
      "box_2d": [610, 628, 664, 906],
      "text_content": "Breakage of glass; falling objects; weight of snow, ice or sleet; freezing (caused by cold weather); collapse or molten material;"
    },
    {
      "box_2d": [609, 117, 622, 129],
      "text_content": "a."
    },
    {
      "box_2d": [611, 145, 681, 454],
      "text_content": "We will not pay for loss, damage or expense caused directly or indirectly by any of the following, whether or not caused by or resulting from an “accident” or “electronic circuitry impairment”:"
    },
    {
      "box_2d": [669, 599, 682, 622],
      "text_content": "(5)"
    },
    {
      "box_2d": [669, 628, 738, 906],
      "text_content": "A hydrostatic, pneumatic or gas pressure test of any boiler or pressure vessel, or an electrical insulation breakdown test of any type of electrical equipment; or"
    },
    {
      "box_2d": [690, 147, 702, 168],
      "text_content": "(1)"
    },
    {
      "box_2d": [690, 174, 702, 406],
      "text_content": "Fire, including smoke from a fire;"
    },
    {
      "box_2d": [744, 599, 757, 622],
      "text_content": "(6)"
    },
    {
      "box_2d": [744, 627, 771, 906],
      "text_content": "Water or other means used to extinguish a fire."
    },
    {
      "box_2d": [706, 145, 718, 167],
      "text_content": "(2)"
    },
    {
      "box_2d": [706, 174, 763, 454],
      "text_content": "Explosion of gas or unconsumed fuel within the furnace of any boiler or fired vessel or within the passages from that furnace to the atmosphere;"
    },
    {
      "box_2d": [780, 569, 792, 583],
      "text_content": "c."
    },
    {
      "box_2d": [777, 145, 793, 168],
      "text_content": "(3)"
    },
    {
      "box_2d": [777, 174, 808, 454],
      "text_content": "Any other explosion, except as specifically covered under this endorsement;"
    },
    {
      "box_2d": [777, 598, 907, 906],
      "text_content": "We will not pay for loss or damaged caused by or resulting from: Depletion, deterioration, corrosion, erosion, wear and tear, or other gradually developing conditions, but if an “accident” or “electronic circuitry impairment” results, we will pay for that resulting loss, damage or expense caused by that “accident” or “electronic circuitry impairment”."
    },
